'use strict';
const $=id=>document.getElementById(id),{delta,duration,days}=Calculator,KEY='fazlamesai-v1';
const labels={work:'Çalışma',normal:'Normal izin',overtime:'Mesai izni'};let state={version:1,people:[],records:[]},editing=null;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function validate(s){if(s.version!==1||!Array.isArray(s.people)||!Array.isArray(s.records))throw Error('Geçersiz yedek biçimi.');const ids=new Set(),rids=new Set(),dates=new Set();for(const p of s.people){if(typeof p.id!=='string'||ids.has(p.id)||typeof p.name!=='string'||!p.name.trim()||p.name.length>80||typeof p.unit!=='string'||p.unit.length>80)throw Error('Geçersiz personel kaydı.');ids.add(p.id);}for(const r of s.records){const d=new Date(r.date+'T12:00:00');if(typeof r.id!=='string'||rids.has(r.id)||!ids.has(r.person)||!/^\d{4}-\d{2}-\d{2}$/.test(r.date)||isNaN(d)||d.getFullYear()!==+r.date.slice(0,4)||d.getMonth()+1!==+r.date.slice(5,7)||d.getDate()!==+r.date.slice(8,10)||!Object.hasOwn(labels,r.type)||!Number.isInteger(r.minutes)||r.minutes<0||r.minutes>1440||typeof r.note!=='string'||r.note.length>250||dates.has(r.person+'|'+r.date))throw Error('Geçersiz veya tekrarlanan günlük kayıt.');if(r.type==='overtime'&&r.minutes===0)throw Error('İzin süresi sıfır olamaz.');rids.add(r.id);dates.add(r.person+'|'+r.date);}return s;}
try{const saved=localStorage.getItem(KEY);if(saved)state=validate(JSON.parse(saved));}catch(e){$('message').textContent='Kayıtlar yüklenemedi: '+e.message+' Mevcut veri korunuyor; kayıt eklemeden önce yedeğini kontrol et.';$('save').disabled=true;}
function persist(next){localStorage.setItem(KEY,JSON.stringify(next));state=next;render();}
function options(){const a=$('person').value,b=$('filter').value;$('person').innerHTML=state.people.length?state.people.map(p=>`<option value="${esc(p.id)}">${esc(p.name)}</option>`).join(''):'<option value="">Önce personel ekle</option>';$('filter').innerHTML='<option value="all">Tüm ekip</option>'+state.people.map(p=>`<option value="${esc(p.id)}">${esc(p.name)}</option>`).join('');if(state.people.some(p=>p.id===a))$('person').value=a;if(b==='all'||state.people.some(p=>p.id===b))$('filter').value=b;}
function render(){options();const records=state.records.filter(r=>$('filter').value==='all'||r.person===$('filter').value),sum=records.reduce((a,r)=>a+delta(r),0);$('balance').textContent=duration(sum);$('balance').className=sum<0?'negative':'positive';$('days').textContent=days(sum);$('earned').textContent=duration(records.reduce((a,r)=>a+Math.max(0,delta(r)),0));$('used').textContent=duration(-records.reduce((a,r)=>a+Math.min(0,delta(r)),0));$('people').innerHTML=state.people.map(p=>`<li>${esc(p.name)} <span class="muted">${esc(p.unit)}</span></li>`).join('')||'<li class="muted">İlk personelini ekleyerek başla.</li>';$('records').innerHTML=records.slice().sort((a,b)=>b.date.localeCompare(a.date)).map(r=>{const d=delta(r),p=state.people.find(p=>p.id===r.person);return `<tr><td>${r.date.split('-').reverse().join('.')}</td><td>${esc(p.name)}</td><td>${labels[r.type]}${r.note?'<br><small class="muted">'+esc(r.note)+'</small>':''}</td><td>${r.type==='normal'?'—':duration(r.minutes)}</td><td class="${d<0?'negative':'positive'}">${d>0?'+':''}${duration(d)}</td><td><button class="textbutton" data-edit="${esc(r.id)}">Düzenle</button> <button class="textbutton" data-delete="${esc(r.id)}">Sil</button></td></tr>`;}).join('')||'<tr><td colspan="6" class="empty">Henüz kayıt yok. İlk günlük kaydını ekle.</td></tr>';$('summary').innerHTML=state.people.map(p=>{const total=state.records.filter(r=>r.person===p.id).reduce((a,r)=>a+delta(r),0);return `<tr><td>${esc(p.name)}</td><td class="${total<0?'negative':'positive'}">${duration(total)}</td><td>${days(total)}</td></tr>`;}).join('')||'<tr><td colspan="3" class="empty">Personel eklediğinde bakiyeler burada görünecek.</td></tr>';preview();}
function formRecord(){const type=$('type').value;let minutes=0;if(type==='work'){const time=v=>{if(!/^\d{2}:\d{2}$/.test(v))throw Error('Başlangıç ve bitiş saatlerini gir.');const [h,m]=v.split(':').map(Number);return h*60+m;};const gross=time($('end').value)-time($('start').value)+($('nextDay').checked?1440:0),rest=Number($('break').value);if(gross<0||gross>1440||!Number.isInteger(rest)||rest<0||rest>gross)throw Error('Saatleri ve mola süresini kontrol et. Gece çalışması için ertesi gün kutusunu işaretle.');minutes=gross-rest;}else if(type==='overtime'){const h=Number($('leaveHours').value),m=Number($('leaveMinutes').value);if(!Number.isInteger(h)||!Number.isInteger(m)||h<0||h>24||m<0||m>59||h*60+m<=0||h*60+m>1440)throw Error('Geçerli bir izin süresi gir.');minutes=h*60+m;}return {id:editing||crypto.randomUUID(),person:$('person').value,date:$('date').value,type,minutes,note:$('note').value.trim(),start:$('start').value,end:$('end').value,rest:Number($('break').value),nextDay:$('nextDay').checked};}
function preview(){$('workFields').hidden=$('type').value!=='work';$('leaveFields').hidden=$('type').value!=='overtime';try{const r=formRecord();$('effect').textContent=r.date?'Bakiye etkisi: '+(delta(r)>0?'+':'')+duration(delta(r)):'';}catch(e){$('effect').textContent=e.message;}}
$('entry').addEventListener('input',preview);$('entry').addEventListener('change',preview);
$('entry').onsubmit=e=>{e.preventDefault();try{const r=formRecord();if(!r.person)throw Error('Önce personel ekle.');if(state.records.some(x=>x.id!==r.id&&x.person===r.person&&x.date===r.date))throw Error('Bu personelin bu tarihte kaydı var. Mevcut kaydı düzenle.');const next={...state,records:[...state.records.filter(x=>x.id!==r.id),r]};validate(next);persist(next);reset();$('message').textContent='Kayıt kaydedildi.';}catch(e){$('message').textContent=e.message;}};
function reset(){editing=null;$('formTitle').textContent='Günlük kayıt ekle';$('save').textContent='Kaydı ekle';$('cancel').hidden=true;$('note').value='';preview();}$('cancel').onclick=reset;$('filter').onchange=render;
$('records').onclick=e=>{const edit=e.target.dataset.edit,del=e.target.dataset.delete;if(edit){const r=state.records.find(x=>x.id===edit);editing=r.id;$('person').value=r.person;$('date').value=r.date;$('type').value=r.type;$('note').value=r.note;$('start').value=r.start||'09:00';$('end').value=r.end||'17:00';$('break').value=r.rest||0;$('nextDay').checked=!!r.nextDay;$('leaveHours').value=Math.floor(r.minutes/60);$('leaveMinutes').value=r.minutes%60;$('formTitle').textContent='Kaydı düzenle';$('save').textContent='Değişiklikleri kaydet';$('cancel').hidden=false;preview();$('entry').scrollIntoView({behavior:'smooth'});}if(del&&confirm('Bu günlük kayıt silinsin mi? Bakiyesi yeniden hesaplanacak.')){try{persist({...state,records:state.records.filter(r=>r.id!==del)});if(editing===del)reset();}catch(e){$('message').textContent='Silinemedi: '+e.message;}}};
$('addPerson').onclick=()=>$('personDialog').showModal();$('closeDialog').onclick=()=>$('personDialog').close();$('personForm').onsubmit=e=>{e.preventDefault();const name=$('name').value.trim();if(!name)return;try{const next={...state,people:[...state.people,{id:crypto.randomUUID(),name,unit:$('unit').value.trim()}]};validate(next);persist(next);$('personDialog').close();$('personForm').reset();}catch(e){alert('Personel eklenemedi: '+e.message);}};
$('export').onclick=()=>{const a=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));a.href=url;a.download='fazlamesai-yedek-'+$('date').value+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};$('import').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>5000000)throw Error('Yedek dosyası çok büyük.');const next=validate(JSON.parse(await file.text()));if(confirm(`${next.people.length} personel ve ${next.records.length} kayıt yüklenecek. Mevcut kayıtların yerini alacak. Devam edilsin mi?`)){persist(next);$('save').disabled=false;reset();$('message').textContent='Yedek yüklendi.';}}catch(e){alert('Yedek yüklenemedi: '+e.message);}finally{e.target.value='';}};
const now=new Date();$('date').value=[now.getFullYear(),String(now.getMonth()+1).padStart(2,'0'),String(now.getDate()).padStart(2,'0')].join('-');render();
